// Pure helpers for the bookmark model (link handling, identity, dedupe).
// Kept DOM-free so they can be unit-tested under Node.

export function normalizeUrl(raw) {
  let u = String(raw == null ? "" : raw).trim();
  if (!u) return "";
  if (!/^https?:\/\//i.test(u)) u = "https://" + u;
  return u;
}

// Light validity check (SCN-011): parses as an http/https URL with a dotted
// hostname and contains no whitespace.
export function isValidLink(url) {
  const u = String(url == null ? "" : url);
  if (/\s/.test(u)) return false;
  try {
    const parsed = new URL(u);
    return /^https?:$/.test(parsed.protocol) && parsed.hostname.includes(".") && parsed.hostname.length >= 3;
  } catch {
    return false;
  }
}

// Link equality for duplicate detection (SCN-009): ignore a trailing slash,
// case-insensitive on scheme + host, path/query preserved (case-insensitive
// overall to be forgiving).
export function sameLink(a, b) {
  return canonicalLink(a) === canonicalLink(b);
}

export function canonicalLink(url) {
  return String(url == null ? "" : url).trim().toLowerCase().replace(/\/+$/, "");
}

export function hostFromUrl(url) {
  try {
    return new URL(url).hostname.replace(/^www\./, "");
  } catch {
    return String(url == null ? "" : url);
  }
}

export function makeId() {
  return "bm_" + Date.now().toString(36) + "_" + Math.random().toString(36).slice(2, 8);
}

// Find an existing bookmark whose link matches (used to prevent duplicates).
export function findDuplicate(bookmarks, url) {
  return bookmarks.find((b) => sameLink(b.url, url)) || null;
}
// Browser-local persistence (SCN-012). The entire collection is stored in
// localStorage so it survives between visits, in the browser it is used in.
// Single user, private — no server-side storage of bookmarks.

const STORAGE_KEY = "bookmarks.v1";

export function loadBookmarks() {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return [];
    const data = JSON.parse(raw);
    if (!Array.isArray(data)) return [];
    return data.map(normalize);
  } catch {
    return [];
  }
}

export function saveBookmarks(bookmarks) {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(bookmarks));
    return true;
  } catch {
    return false;
  }
}

// Ensure each loaded record has the expected shape (forward/backward safety).
function normalize(b) {
  return {
    id: b.id || "bm_" + Math.random().toString(36).slice(2),
    url: b.url || "",
    title: b.title || "",
    description: b.description || "",
    host: b.host || "",
    favicon: b.favicon || "",
    image: b.image || "",
    tags: Array.isArray(b.tags) ? b.tags : [],
    note: b.note || "",
    readLater: !!b.readLater,
    archived: !!b.archived,
    edited: !!b.edited,
    error: !!b.error,
    createdAt: b.createdAt || Date.now(),
  };
}

export { STORAGE_KEY };
// Search query language for bookmarks (SCN-005).
//
// Grammar (case-insensitive), precedence NOT > AND > OR, implicit AND between
// adjacent terms:
//   orExpr  := andExpr (OR andExpr)*
//   andExpr := notExpr ((AND)? notExpr)*
//   notExpr := (NOT | -) notExpr | atom
//   atom    := '(' orExpr ')' | term
//   term    := "quoted phrase" | #tag | word
//
// A term is one of:
//   #tag           -> EXACT (case-insensitive) match against the record's tags
//   "quoted phrase"-> loose substring match of the phrase against the haystack
//   word           -> loose substring match against the haystack
//
// buildMatcher(input) returns a predicate over a "record":
//   { haystack: string (already lowercased), tags: string[] (already lowercased) }
// or null when the input is empty. A malformed query falls back to a plain
// substring match of the whole input (SCN-005 assumption).

export function buildMatcher(input) {
  const source = String(input == null ? "" : input);
  const tokens = tokenize(source);
  if (tokens.length === 0) return null;

  let pos = 0;
  const peek = () => tokens[pos];
  const eat = () => tokens[pos++];
  const isKeyword = (t, word) => t && t.type === "word" && t.value.toUpperCase() === word;

  function parseOr() {
    let left = parseAnd();
    while (isKeyword(peek(), "OR")) {
      eat();
      const right = parseAnd();
      const l = left;
      left = (r) => l(r) || right(r);
    }
    return left;
  }

  function parseAnd() {
    let left = parseNot();
    while (peek() && !isKeyword(peek(), "OR") && peek().type !== "rparen") {
      if (isKeyword(peek(), "AND")) eat();
      const right = parseNot();
      const l = left;
      left = (r) => l(r) && right(r);
    }
    return left;
  }

  function parseNot() {
    const t = peek();
    if (isKeyword(t, "NOT") || (t && t.type === "neg")) {
      eat();
      const inner = parseNot();
      return (r) => !inner(r);
    }
    return parseAtom();
  }

  function parseAtom() {
    const t = peek();
    if (t && t.type === "lparen") {
      eat();
      const inner = parseOr();
      if (peek() && peek().type === "rparen") eat();
      return inner;
    }
    eat();
    return termPredicate(t);
  }

  try {
    const predicate = parseOr();
    // Defensive: if parsing left tokens unconsumed in a weird way, still usable.
    return predicate;
  } catch (err) {
    const needle = source.trim().toLowerCase();
    return (r) => r.haystack.includes(needle);
  }
}

function termPredicate(token) {
  if (!token) return () => true;
  if (token.type === "tag") {
    const name = token.value.toLowerCase();
    return (r) => r.tags.includes(name);
  }
  // word or phrase
  const needle = token.value.toLowerCase();
  if (!needle) return () => true;
  return (r) => r.haystack.includes(needle);
}

function tokenize(input) {
  const tokens = [];
  const re = /\s*("[^"]*"|#[^\s()]+|\(|\)|-(?=\S)|[^\s()]+)/g;
  let m;
  while ((m = re.exec(input)) !== null) {
    const raw = m[1];
    if (raw === "(") tokens.push({ type: "lparen" });
    else if (raw === ")") tokens.push({ type: "rparen" });
    else if (raw === "-") tokens.push({ type: "neg" });
    else if (raw.startsWith("#")) tokens.push({ type: "tag", value: raw.slice(1) });
    else if (raw.length >= 2 && raw.startsWith('"') && raw.endsWith('"')) {
      tokens.push({ type: "word", value: raw.slice(1, -1) });
    } else {
      tokens.push({ type: "word", value: raw });
    }
  }
  return tokens;
}

// Build the normalized record a matcher expects from a bookmark object.
export function toRecord(bookmark) {
  const tags = Array.isArray(bookmark.tags) ? bookmark.tags : [];
  const haystack = [
    bookmark.title,
    bookmark.description,
    bookmark.note,
    bookmark.url,
    tags.join(" "),
    bookmark.host,
  ]
    .filter(Boolean)
    .join(" ")
    .toLowerCase();
  return { haystack, tags: tags.map((t) => String(t).toLowerCase()) };
}
